/*
 * A296750  Numbers whose base-13 digits d(m), d(m-1), ..., d(0) have #(rises)
 *          = #(falls); see Comments.
 * https://oeis.org/A296750
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   generated by enumerating all natural numbers whose base‑13 *
 *            digits have an equal number of rises and falls. This implements
 *            * the nth element of OEIS A296750
 * Range:     u8 n <= 57, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   equal_rise_fall
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/equal_rise_fall.h"

/* ----- dynamic cache for already found terms ----- */
static seq_t *cache        = NULL;   /* array of found terms           */
static idx_t cache_cap     = 0;      /* allocated capacity             */
static idx_t cache_len     = 0;      /* number of terms stored         */
static idx_t last_checked  = 1;      /* next integer to examine        */

/* enlarge the cache if needed */
static void ensure_capacity(void)
{
    if (cache_len == cache_cap) {
        cache_cap = cache_cap ? cache_cap * 2 : 16;
        cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
    }
}

/* store a new term in the cache */
static void add_term(seq_t val)
{
    ensure_capacity();
    cache[cache_len++] = val;
}

/* ----- public sequence function ----- */
seq_t a(idx_t n)
{
    if (n == 0)           /* undefined for 0, return 0 for safety */
        return (seq_t)0;

    /* generate terms until we have at least n of them */
    while (cache_len < n) {
        seq_t candidate = (seq_t)last_checked;
        if (equal_rise_fall(candidate)) {
            add_term(candidate);
        }
        ++last_checked;   /* advance to the next integer */
    }
    return cache[n - 1];
}
